-- Help Desk R3: status pages, internal and public.
--
--   hd_status_pages          a page; a public page is reached by its public_key (generated by the
--                            backend: at least 32 random URL-safe characters, unique everywhere)
--   hd_status_components     what the page shows, optionally tied to a CI
--   hd_status_events         incidents and maintenance on a page, tied to a major incident or a change
--   hd_status_event_updates  append-only: what was posted on an event
--   hd_status_subscribers    email subscribers (double opt-in: confirm_token, then confirmed_at)
--
-- The public routes look rows up by public_key and by token without a business in hand, so those
-- keys are unique across every business. CHECK lists are defined here, inline; a later change goes
-- in a newer file. No grants.
-- Design: tvs-shared-apps-bk docs/helpdesk/contracts/R3.md §3, §6. Idempotent; safe to re-run.

BEGIN;

-- ============================================================================= pages
CREATE TABLE IF NOT EXISTS helpdesk.hd_status_pages (
    id          text PRIMARY KEY DEFAULT gen_random_uuid()::text,
    tenant_id   text NOT NULL,
    bus_id      text NOT NULL,
    name        text NOT NULL,
    visibility  text NOT NULL DEFAULT 'internal'
                CONSTRAINT hd_status_pages_visibility_check CHECK (visibility IN ('internal', 'public')),
    public_key  text CONSTRAINT hd_status_pages_public_key_check CHECK (length(public_key) >= 32 AND public_key ~ '^[A-Za-z0-9_-]+$'),
    intro       text,
    is_active   boolean NOT NULL DEFAULT true,
    cdatetime   timestamptz NOT NULL DEFAULT now(),
    created_by  text,
    updated_at  timestamptz,
    updated_by  text,
    -- A public page can be reached only through its key.
    CONSTRAINT hd_status_pages_public_needs_key CHECK (visibility <> 'public' OR public_key IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS hd_status_pages_public_key_uq ON helpdesk.hd_status_pages (public_key) WHERE public_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS hd_status_pages_business_idx ON helpdesk.hd_status_pages (tenant_id, bus_id);

-- ======================================================================== components
CREATE TABLE IF NOT EXISTS helpdesk.hd_status_components (
    id          text PRIMARY KEY DEFAULT gen_random_uuid()::text,
    tenant_id   text NOT NULL,
    bus_id      text NOT NULL,
    page_id     text NOT NULL REFERENCES helpdesk.hd_status_pages (id),
    ci_id       text REFERENCES helpdesk.hd_cis (id),
    name        text NOT NULL,
    position    int NOT NULL DEFAULT 0,
    state       text NOT NULL DEFAULT 'operational'
                CONSTRAINT hd_status_components_state_check CHECK (state IN ('operational', 'degraded', 'partial_outage', 'major_outage', 'maintenance')),
    cdatetime   timestamptz NOT NULL DEFAULT now(),
    created_by  text,
    updated_at  timestamptz,
    updated_by  text
);
CREATE INDEX IF NOT EXISTS hd_status_components_page_idx ON helpdesk.hd_status_components (page_id, position);

-- ============================================================================ events
-- An incident moves investigating -> identified -> monitoring -> resolved; maintenance moves
-- scheduled -> in_progress -> completed.
CREATE TABLE IF NOT EXISTS helpdesk.hd_status_events (
    id             text PRIMARY KEY DEFAULT gen_random_uuid()::text,
    tenant_id      text NOT NULL,
    bus_id         text NOT NULL,
    page_id        text NOT NULL REFERENCES helpdesk.hd_status_pages (id),
    kind           text NOT NULL CONSTRAINT hd_status_events_kind_check CHECK (kind IN ('incident', 'maintenance')),
    title          text NOT NULL,
    state          text NOT NULL
                   CONSTRAINT hd_status_events_state_check CHECK (state IN ('investigating', 'identified', 'monitoring', 'resolved',
                       'scheduled', 'in_progress', 'completed')),
    component_ids  text[] NOT NULL DEFAULT '{}',
    major_id       text REFERENCES helpdesk.hd_major_incidents (id),
    change_id      text REFERENCES helpdesk.hd_changes (id),
    starts_at      timestamptz,
    ends_at        timestamptz,
    is_public      boolean NOT NULL DEFAULT false,
    cdatetime      timestamptz NOT NULL DEFAULT now(),
    created_by     text,
    updated_at     timestamptz,
    updated_by     text,
    CONSTRAINT hd_status_events_kind_state_check CHECK (
        (kind = 'incident' AND state IN ('investigating', 'identified', 'monitoring', 'resolved'))
        OR (kind = 'maintenance' AND state IN ('scheduled', 'in_progress', 'completed'))),
    CONSTRAINT hd_status_events_dates_check CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at >= starts_at)
);
CREATE INDEX IF NOT EXISTS hd_status_events_page_idx ON helpdesk.hd_status_events (page_id, starts_at DESC);

CREATE TABLE IF NOT EXISTS helpdesk.hd_status_event_updates (
    id          text PRIMARY KEY DEFAULT gen_random_uuid()::text,
    tenant_id   text NOT NULL,
    bus_id      text NOT NULL,
    event_id    text NOT NULL REFERENCES helpdesk.hd_status_events (id),
    state       text NOT NULL
                CONSTRAINT hd_status_event_updates_state_check CHECK (state IN ('investigating', 'identified', 'monitoring', 'resolved',
                    'scheduled', 'in_progress', 'completed')),
    body        text NOT NULL,
    posted_by   text,
    cdatetime   timestamptz NOT NULL DEFAULT now(),
    created_by  text,
    updated_at  timestamptz,
    updated_by  text
);
CREATE INDEX IF NOT EXISTS hd_status_event_updates_event_idx ON helpdesk.hd_status_event_updates (event_id, cdatetime);
DROP TRIGGER IF EXISTS hd_status_event_updates_append_only ON helpdesk.hd_status_event_updates;
CREATE TRIGGER hd_status_event_updates_append_only BEFORE UPDATE OR DELETE ON helpdesk.hd_status_event_updates
    FOR EACH ROW EXECUTE FUNCTION helpdesk.hd_refuse_change();

-- ======================================================================= subscribers
CREATE TABLE IF NOT EXISTS helpdesk.hd_status_subscribers (
    id                 text PRIMARY KEY DEFAULT gen_random_uuid()::text,
    tenant_id          text NOT NULL,
    bus_id             text NOT NULL,
    page_id            text NOT NULL REFERENCES helpdesk.hd_status_pages (id),
    email              text NOT NULL,
    confirm_token      text,
    confirmed_at       timestamptz,
    unsubscribe_token  text,
    unsubscribed_at    timestamptz,
    cdatetime          timestamptz NOT NULL DEFAULT now(),
    created_by         text,
    updated_at         timestamptz,
    updated_by         text
);
CREATE UNIQUE INDEX IF NOT EXISTS hd_status_subscribers_email_uq ON helpdesk.hd_status_subscribers (page_id, lower(email));
CREATE UNIQUE INDEX IF NOT EXISTS hd_status_subscribers_confirm_uq
    ON helpdesk.hd_status_subscribers (confirm_token) WHERE confirm_token IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS hd_status_subscribers_unsubscribe_uq
    ON helpdesk.hd_status_subscribers (unsubscribe_token) WHERE unsubscribe_token IS NOT NULL;

-- ===================================================================== invariants
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_trigger g JOIN pg_proc p ON p.oid = g.tgfoid
                    WHERE g.tgrelid = 'helpdesk.hd_status_event_updates'::regclass AND p.proname = 'hd_refuse_change'
                      AND NOT g.tgisinternal AND (g.tgtype & 8) <> 0 AND (g.tgtype & 16) <> 0) THEN
        RAISE EXCEPTION 'helpdesk.hd_status_event_updates is not append-only: its hd_refuse_change trigger on UPDATE and DELETE is missing';
    END IF;
    IF to_regclass('helpdesk.hd_status_pages_public_key_uq') IS NULL THEN
        RAISE EXCEPTION 'hd_status_pages has no unique index on public_key';
    END IF;
    IF EXISTS (SELECT 1 FROM helpdesk.hd_status_components c JOIN helpdesk.hd_status_pages p ON p.id = c.page_id
                WHERE p.tenant_id <> c.tenant_id OR p.bus_id <> c.bus_id) THEN
        RAISE EXCEPTION 'a Help Desk status component belongs to a page of another business';
    END IF;
    IF EXISTS (SELECT 1 FROM helpdesk.hd_status_events e JOIN helpdesk.hd_status_pages p ON p.id = e.page_id
                WHERE p.tenant_id <> e.tenant_id OR p.bus_id <> e.bus_id) THEN
        RAISE EXCEPTION 'a Help Desk status event belongs to a page of another business';
    END IF;
    IF EXISTS (SELECT 1 FROM helpdesk.hd_status_events e JOIN helpdesk.hd_major_incidents m ON m.id = e.major_id
                WHERE m.tenant_id <> e.tenant_id OR m.bus_id <> e.bus_id) THEN
        RAISE EXCEPTION 'a Help Desk status event names a major incident of another business';
    END IF;
    IF EXISTS (SELECT 1 FROM helpdesk.hd_status_events e JOIN helpdesk.hd_changes c ON c.id = e.change_id
                WHERE c.tenant_id <> e.tenant_id OR c.bus_id <> e.bus_id) THEN
        RAISE EXCEPTION 'a Help Desk status event names a change of another business';
    END IF;
    IF EXISTS (SELECT 1 FROM helpdesk.hd_status_event_updates u JOIN helpdesk.hd_status_events e ON e.id = u.event_id
                WHERE e.tenant_id <> u.tenant_id OR e.bus_id <> u.bus_id) THEN
        RAISE EXCEPTION 'a Help Desk status update belongs to an event of another business';
    END IF;
    IF EXISTS (SELECT 1 FROM helpdesk.hd_status_subscribers s JOIN helpdesk.hd_status_pages p ON p.id = s.page_id
                WHERE p.tenant_id <> s.tenant_id OR p.bus_id <> s.bus_id) THEN
        RAISE EXCEPTION 'a Help Desk status subscriber belongs to a page of another business';
    END IF;
END $$;

COMMIT;
